database = FileAttachment("spring-37040.db.sqlite3").sqlite()

function k(d) {
  return Number(d3.utcFormat('%Y')(d)) +1
}
















db = database.sql`SELECT year, std_title as label, counts, rel as relative, gender, journal_fk from data`

title_w_count = database.sql`select std_title as label, sum(counts) as count, journal_fk from data group by label, journal_fk`

journals = [ {id:1, name:'All of KB'}, {id:2, name:"Dagens Nyheter"} ]
genders = [ ... new Set(db.map((d) =&gt; d.gender))]






























viewof journal = Inputs.select(journals,
  {label: html`Newspaper`,
    format: (t) =&gt; t.name,
    value: (t) =&gt; t.id,
    size : 2
  })

used_titles = title_w_count.filter((d) =&gt; (d.journal_fk == journal.id))

viewof titles = Inputs.select(reduced,
  {label: html`Titles`,
    value: (t) =&gt; t.label,
    format: (t) =&gt; `${t.label} (${t.count})`,
    multiple: true,
    size : 42,
    width: 350,
  })
titles_only = titles.map(d =&gt; d.label)

viewof title_target = Inputs.text({placeholder: "Filter titles"})

reduced = used_titles.filter((d) =&gt; (d.label.toLowerCase().includes(title_target)))
reduced_titles = reduced.map(d =&gt; d.label)



















































journal_filter = (d) =&gt; d.journal_fk == journal.id

title_filter = reduced.length === 0 ?  (d) =&gt; (true) : titles.length === 0 ? (d) =&gt; reduced_titles.includes(d.label) : (d) =&gt; titles_only.includes(d.label)


timeline_data = db.filter(journal_filter)
                    .filter(title_filter).map((d) =&gt; ({
                      year : new Date(d.year, 0, 1),
                      counts : d.counts,
                      title : d.title,
                      label : d.label,
                      relative : d.relative,
                    }))























Hits (pages)

Plot.plot({
    x: {
    label: "Year",
    tickformat: k,
  },
  y:{
    label: "Number of page hits",
    grid: true
  },
    // color: {legend: true},
    marks: [
      // Plot.ruleY([0, ylim]),

      Plot.lineY(timeline_data, {
        x: "year",
        y: (d) =&gt; d.counts,
        stroke:'label', curve: "catmull-rom"}, ),
      Plot.ruleX(timeline_data, Plot.pointerX({
        py: "counts",
        x: "year",
        stroke: 'red',
        format: k
        })),
    Plot.tip(timeline_data, Plot.pointer({
      x: "year",
      y: "counts",
      title: (d) =&gt; `${d.label}: ${d.value}\nYear: ${d.year}`
    }))
  ],
})








